parameters.jsCode:
const report = $('Claude API').item.json.content[0].text;
const today = new Date().toLocaleDateString('en-NZ');

const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
  body { font-family: Arial, sans-serif; margin: 40px; color: #333; }
  .header { border-bottom: 3px solid #1a1a2e; padding-bottom: 20px; margin-bottom: 30px; }
  .company-name { font-size: 24px; font-weight: bold; color: #1a1a2e; }
  .report-title { font-size: 18px; color: #666; margin-top: 5px; }
  .content { white-space: pre-wrap; line-height: 1.8; font-size: 14px; }
  .footer { border-top: 1px solid #ccc; margin-top: 40px; padding-top: 15px; font-size: 12px; color: #999; }
</style>
</head>
<body>
  <div class="header">
    <div class="company-name">{{COMPANY_NAME}}</div>
    <div class="report-title">Job Service Report — ${today}</div>
  </div>
  <div class="content">${report}</div>
  <div class="footer">
    {{COMPANY_NAME}} | {{COMPANY_PHONE}} | {{COMPANY_EMAIL}}<br>
    This report was generated automatically.
  </div>
</body>
</html>
`;

return [{ json: { html } }];

